    // ————— HPASSIST MODULE v0.3.0 —————
    // =============================================================================
    // [GAMEASSIST:MODULES:HPASSIST] BEGIN
    // Section Title: HPAssist module
    // -------------------------------------------------------------------------
    // mechsuit_section: { codename: "GAMEASSIST", area: "MODULES:HPASSIST", title: "HPAssist",
    //   guarantees: ["Parse NdM±K and set HealthService's configured NPC HP bar to rolled current and maximum HP","Use HealthService for verified producer-identified initialization or synchronization writes when available; preserve direct HP rolling when the optional service is disabled","Case-insensitive !HP-<command>, !hp <command>, and !HPAssist <command> routes own every public HPAssist action; older HP command families remain compatibility-only aliases"],
    //   last_updated_version: "v2.0.0",
    //   independent_versions: { module_version: "0.3.0" } }
    // -------------------------------------------------------------------------
    // Narrative
    // MODULES:HPASSIST parses `npc_hpformula`, rolls HP, and writes to the configured HP bar
    // without altering defaults. It keeps the legacy dice parsing semantics and bar writes
    // while surfacing warnings when formulas are invalid.
    // -------------------------------------------------------------------------
    GameAssist.register('HPAssist', function() {
        const modState = GameAssist.getState('HPAssist');
        const MODULE_VERSION = '0.3.0';

    Object.assign(modState.config, {
        enabled: true,
        autoRollOnAdd: false,
        ...modState.config
    });

        function hpFields() {
            return GameAssist.HealthService?.getHpFields?.() || {
                bar: 'bar1', label: 'Bar 1', current: 'bar1_value', maximum: 'bar1_max', link: 'bar1_link'
            };
        }

        function parseDiceString(diceStr) {
            // Match “NdM”, “NdM+K”, “NdM + K”, “NdM-K”, case-insensitive on “d”
            const match = diceStr.match(
                /^\s*(\d+)\s*[dD]\s*(\d+)(?:\s*([+-])\s*(\d+))?\s*$/
            );
            if (!match) return null;

            const count = parseInt(match[1], 10);
            const sides = parseInt(match[2], 10);
            const sign  = match[3] === '-' ? -1 : 1;
            const bonus = match[4] ? sign * parseInt(match[4], 10) : 0;

            return { count, sides, bonus };
        }

        function rollDice(count, sides) {
            let total = 0;
            for (let i = 0; i < count; i++) {
                total += Math.floor(Math.random() * sides) + 1;
            }
            return total;
        }

        function rollHP(diceData) {
            const { count, sides, bonus } = diceData;
            return rollDice(count, sides) + bonus;
        }

        function resolveNpcContext(token, { logWarnings = true } = {}) {
            if (!token) {
                if (logWarnings) {
                    GameAssist.log('HPAssist', 'Token not found', 'WARN');
                }
                return null;
            }

            const linked = GameAssist.getLinkedCharacter(token);
            if (!linked) {
                if (logWarnings) {
                    GameAssist.log('HPAssist', `${token.get('name') || 'Token'} must be linked to a character on the Objects layer.`, 'WARN');
                }
                return null;
            }

            const displayName = token.get('name') || linked.character.get('name') || 'Token';

            const npcAttr = findObjs({
                _type: 'attribute',
                _characterid: linked.character.id,
                name: 'npc'
            })[0];

            if (!npcAttr || npcAttr.get('current') !== '1') {
                if (logWarnings) {
                    GameAssist.log('HPAssist', `${displayName} is not flagged as an NPC.`, 'WARN');
                }
                return null;
            }

            const hpFormulaAttr = findObjs({
                _type: 'attribute',
                _characterid: linked.character.id,
                name: 'npc_hpformula'
            })[0];

            if (!hpFormulaAttr) {
                if (logWarnings) {
                    GameAssist.log('HPAssist', `No HP formula found for ${displayName}`, 'WARN');
                }
                return null;
            }

            const formula = hpFormulaAttr.get('current');
            const diceData = parseDiceString(formula);

            if (!diceData) {
                if (logWarnings) {
                    GameAssist.log('HPAssist', `Invalid HP formula: ${formula}`, 'WARN');
                }
                return null;
            }

            return { linked, formula, diceData, displayName };
        }

        function rollTokenHP(token, { logWarnings = true, reason = 'manual' } = {}) {
            const context = resolveNpcContext(token, { logWarnings });
            if (!context) return false;

            const hp = rollHP(context.diceData);

            if (GameAssist.HealthService?.isEnabled()) {
                const before = GameAssist.HealthService.readToken(token);
                const classification = before?.values?.current?.state === 'valid'
                    ? 'synchronization'
                    : 'initialization';
                const result = GameAssist.HealthService.writeToken({
                    token,
                    current: hp,
                    maximum: hp,
                    producer: 'HPAssist',
                    operationId: `hp-roll:${Date.now().toString(36)}:${randomInteger(999999)}`,
                    classification
                });
                if (!result.ok) {
                    if (logWarnings) GameAssist.log('HPAssist', `${context.displayName} HP could not be verified: ${result.message}`, 'WARN');
                    return false;
                }
            } else {
                // CHOICE: HPAssist remains independently usable when HealthService is deliberately disabled; only provenance-aware integration is unavailable.
                const fields = hpFields();
                token.set(fields.current, hp);
                token.set(fields.maximum, hp);
            }

            const suffix = reason === 'auto' ? ' (auto-roll on add)' : '';
            GameAssist.log('HPAssist', `${context.displayName} HP set to ${hp} using [${context.formula}]${suffix}`);
            return true;
        }

        function sendNpcHpPanel(title, fields) {
            const body = fields.map(field => `{{${_sanitize(field.label)}=${field.value}}}`).join(' ');
            sendChat('HPAssist', `/w gm &{template:default} {{name=${_sanitize(title)}}} ${body}`);
        }

        function showNpcHpGuide() {
            sendNpcHpPanel('HPAssist Guide', [
                { label: 'Actions', value: `${GameAssist.createButton('Roll Selected NPCs', '!HP-Selected')} ${GameAssist.createButton('Roll Page NPCs', '!HP-All')} ${GameAssist.createButton('Current Status', '!HP-Status')}` },
                { label: 'Learn Or Review', value: `${GameAssist.createButton('What does HPAssist do?', '!HP-Info')} ${GameAssist.createButton('Read-Only Audit', '!HP-Audit')} ${GameAssist.createButton('Settings', '!HP-Settings')}` }
            ]);
        }

        function showNpcHpControl() {
            const counts = inspectNpcHpPage();
            sendNpcHpPanel('HPAssist GM Controls', [
                { label: 'Current Page', value: `${counts.eligible} eligible NPCs | ${counts.invalid} need an HP formula` },
                { label: 'Roll HP', value: `${GameAssist.createButton('Selected NPCs', '!HP-Selected')} ${GameAssist.createButton('All Page NPCs', '!HP-All')}` },
                { label: 'Review And Setup', value: `${GameAssist.createButton('Status', '!HP-Status')} ${GameAssist.createButton('Read-Only Audit', '!HP-Audit')} ${GameAssist.createButton('Settings', '!HP-Settings')} ${GameAssist.createButton('Guide', '!HP-Guide')}` },
                { label: 'GameAssist', value: gameAssistHomeButton() }
            ]);
        }

        function showNpcHpInfo() {
            sendNpcHpPanel('What HPAssist Does', [
                { label: 'Purpose', value: `Rolls each qualifying linked NPC's npc_hpformula and writes the result to ${hpFields().label} current and maximum HP.` },
                { label: 'At The Table', value: 'Select NPC tokens for a deliberate roll, or roll every qualifying NPC on the current player page. Player characters, unlinked tokens, and invalid formulas are skipped.' },
                { label: 'Guide', value: `${GameAssist.createButton('Back to Guide', '!HP-Guide')} ${GameAssist.createButton('Read-Only Audit', '!HP-Audit')}` }
            ]);
        }

        function inspectNpcHpPage() {
            const pageId = Campaign().get('playerpageid');
            const tokens = pageId ? findObjs({ _pageid: pageId, _type: 'graphic', layer: 'objects' }) : [];
            const counts = { total: tokens.length, eligible: 0, unlinked: 0, pc: 0, invalid: 0 };
            tokens.forEach(token => {
                const linked = GameAssist.getLinkedCharacter(token);
                if (!linked) {
                    counts.unlinked++;
                    return;
                }
                const npc = String(getAttrByName(linked.character.id, 'npc') || '') === '1';
                if (!npc) {
                    counts.pc++;
                    return;
                }
                const formula = String(getAttrByName(linked.character.id, 'npc_hpformula') || '');
                if (!parseDiceString(formula)) {
                    counts.invalid++;
                    return;
                }
                counts.eligible++;
            });
            return counts;
        }

        function showNpcHpStatus(audit = false) {
            const counts = inspectNpcHpPage();
            const fields = [
                { label: 'Module', value: `${MODULE_VERSION} | enabled and responding` },
                { label: 'Automatic Roll On Add', value: modState.config.autoRollOnAdd === true ? 'On' : 'Off' },
                { label: 'Current Page', value: `${counts.eligible} eligible NPCs | ${counts.pc} player characters | ${counts.unlinked} unlinked items | ${counts.invalid} NPCs with missing or invalid formulas` },
                { label: 'Actions', value: `${GameAssist.createButton('Roll Selected', '!HP-Selected')} ${GameAssist.createButton('Open Guide', '!HP-Guide')}` }
            ];
            if (audit) fields.splice(3, 0, { label: 'Changes', value: `None. This audit checks linkage, NPC flags, and HP formulas without rolling or changing ${hpFields().label}.` });
            sendNpcHpPanel(audit ? 'HPAssist Audit' : 'HPAssist Status', fields);
        }

        function showNpcHpSettings() {
            const enabled = modState.config.autoRollOnAdd === true;
            sendNpcHpPanel('HPAssist Settings', [
                { label: 'Automatic Roll On Add', value: `${enabled ? 'On' : 'Off'} ${GameAssist.createButton(enabled ? 'Turn Off' : 'Turn On', `!ga-config set HPAssist autoRollOnAdd=${enabled ? 'false' : 'true'}`)}` },
                { label: 'NPC HP Bar', value: `${hpFields().label} ${GameAssist.createButton('Choose Or Prepare HP Bars', '!ga-health bars')}` },
                { label: 'Behavior', value: 'When enabled, newly added qualifying NPC tokens receive rolled HP. Setup protection prevents that initialization from creating false NPCAssist death or revival history.' },
                { label: 'Return', value: GameAssist.createButton('Back to Guide', '!HP-Guide') }
            ]);
        }

        function showNpcHpManualNotice() {
            sendNpcHpPanel('HPAssist Guide', [
                { label: 'Manual', value: 'HPAssist is intentionally small, so its complete instructions stay in the compact chat guide instead of creating another campaign handout.' },
                { label: 'Continue', value: `${GameAssist.createButton('Open Guide', '!HP-Guide')} ${GameAssist.createButton('Read-Only Audit', '!HP-Audit')}` }
            ]);
        }

        const npcHpDashActions = {
            help: showNpcHpGuide,
            guide: showNpcHpGuide,
            menu: showNpcHpControl,
            gm: showNpcHpControl,
            dm: showNpcHpControl,
            info: showNpcHpInfo,
            about: showNpcHpInfo,
            status: () => showNpcHpStatus(false),
            refresh: () => showNpcHpStatus(false),
            audit: () => showNpcHpStatus(true),
            settings: showNpcHpSettings,
            config: showNpcHpSettings,
            manual: showNpcHpManualNotice,
            all: rollAllNpcHp,
            selected: rollSelectedNpcHp
        };

        function handleNpcHpDashCommand(msg) {
            const command = String(msg.content || '').trim().split(/\s+/)[0].toLowerCase();
            const match = command.match(/^!(?:hp|hpassist|npchp|npchproller|npc-hp)-([a-z]+)$/);
            const handler = match ? npcHpDashActions[match[1]] : null;
            if (handler) return handler(msg);
            sendNpcHpPanel('HPAssist', [
                { label: 'Needs Attention', value: 'That HPAssist command was not recognized.' },
                { label: 'Next Step', value: GameAssist.createButton('Open Guide', '!HP-Guide') }
            ]);
        }

        ['!HP-', '!HPAssist-', '!NPCHP-', '!NPCHPRoller-', '!npc-hp-'].forEach(prefix => {
            GameAssist.onCommand(prefix, handleNpcHpDashCommand, 'HPAssist', {
                gmOnly: true,
                match: { caseInsensitive: true, mode: 'prefix' }
            });
        });

        function rollAllNpcHp() {
            const pageId = Campaign().get('playerpageid');
            const tokens = findObjs({
                _pageid: pageId,
                _type: 'graphic',
                layer: 'objects'
            });

            const npcTokens = [];
            const skipped = [];

            for (const token of tokens) {
                const link = GameAssist.getLinkedCharacter(token);
                if (!link) {
                    skipped.push(token.get('name') || '(Unnamed)');
                    continue;
                }

                const npcAttr = findObjs({
                    _type: 'attribute',
                    _characterid: link.character.id,
                    name: 'npc'
                })[0];

                if (npcAttr && npcAttr.get('current') === '1') {
                    npcTokens.push(token);
                }
            }

            GameAssist.log('HPAssist', `Rolling HP for ${npcTokens.length} NPCs on current map...`);

            for (const token of npcTokens) {
                try {
                    rollTokenHP(token);
                } catch (err) {
                    GameAssist.log('HPAssist', `Error processing ${token.get('name')}: ${err.message}`, 'ERROR');
                }
            }

            if (skipped.length) {
                GameAssist.log('HPAssist', `Skipped ${skipped.length} token(s) without linked characters: ${skipped.join(', ')}`, 'WARN');
            }
        }

        function rollSelectedNpcHp(msg) {
            if (!msg.selected || msg.selected.length === 0) {
                GameAssist.log('HPAssist', 'No tokens selected', 'WARN');
                return;
            }

            const skipped = [];

            msg.selected.forEach(sel => {
                const token = getObj('graphic', sel._id);
                if (!token) {
                    skipped.push('(Missing Token)');
                    return;
                }

                if (!GameAssist.getLinkedCharacter(token)) {
                    skipped.push(token.get('name') || '(Unnamed)');
                    return;
                }

                try {
                    rollTokenHP(token);
                } catch (err) {
                    GameAssist.log('HPAssist', `Error processing ${token.get('name')}: ${err.message}`, 'ERROR');
                }
            });

            if (skipped.length) {
                GameAssist.log('HPAssist', `Skipped ${skipped.length} token(s): ${skipped.join(', ')}`, 'WARN');
            }
        }

        function handleHpCommand(msg) {
            const raw = String(msg.content || '').trim().toLowerCase();
            const body = raw.replace(/^!(?:hp|hpassist)(?:\s+|$)/i, '').trim();
            const command = body.split(/\s+/)[0];
            if (!command || command === 'menu' || command === 'gm' || command === 'dm') return showNpcHpControl();
            if (command === 'help' || command === 'guide') return showNpcHpGuide();
            if (command === 'info' || command === 'about') return showNpcHpInfo();
            if (command === 'status' || command === 'refresh') return showNpcHpStatus(false);
            if (command === 'audit') return showNpcHpStatus(true);
            if (command === 'settings' || command === 'config') return showNpcHpSettings();
            if (command === 'manual') return showNpcHpManualNotice();
            if (command === 'all') return rollAllNpcHp();
            if (command === 'selected') return rollSelectedNpcHp(msg);
            sendNpcHpPanel('HPAssist', [
                { label: 'Needs Attention', value: 'That HPAssist command was not recognized.' },
                { label: 'Next Step', value: GameAssist.createButton('Open Guide', '!HP-Guide') }
            ]);
        }

        GameAssist.onCommand('!hp', handleHpCommand, 'HPAssist', { gmOnly: true });
        GameAssist.onCommand('!HPAssist', handleHpCommand, 'HPAssist', { gmOnly: true });

        GameAssist.onEvent('add:graphic', token => {
            if (!modState.config.autoRollOnAdd) return;
            rollTokenHP(token, { logWarnings: false, reason: 'auto' });
        }, 'HPAssist');

    GameAssist.log('HPAssist', `v${MODULE_VERSION} Ready: !HP-Guide, !HP-All, !HP-Selected, or !hp guide`, 'INFO', { startup: true });
}, {
    enabled: true,
    events: ['add:graphic'],
        prefixes: ['!HP-', '!hp', '!HPAssist', '!HPAssist-', '!npc-hp-', '!NPCHP-', '!NPCHPRoller-']
});
    // --- Notes & Comments ---
    // Changed (v2.0.0): Advanced HPAssist to 0.3.0; verified and fallback HP rolls follow HealthService's configured NPC HP bar, the settings screen links to shared bar setup, and bare !hpassist opens the GM control center.
    // Changed (v2.0.0): Added the standard GameAssist Home return to the HPAssist GM control screen.
    // Changed (v2.0.0): Routed supported HP rolls through HealthService with producer, operation, initialization/synchronization, deduplication, and verification evidence while retaining direct writes when the optional service is deliberately disabled.
    // Decision log:
    //   CHOICE: Keep the complete short guide in chat - ALT: create a persistent manual handout; REJECTED: the module's ordinary workflow fits in a compact panel and another handout would add campaign clutter.
    //   CHOICE: Use Math.random for simplicity; acceptable for non-critical HP rolls.
    // Prior notes:
    //   v1.8.2: Made case-insensitive !HP-<command> and !hp <command> the generated and documented HPAssist interface; retained older !HPAssist-*, !npc-hp-*, !NPCHP-*, and !NPCHPRoller-* forms only as compatibility aliases, and prevented NPCAssist from intercepting the !npc-hp-* family.
    //   v1.8.0: Renamed the module to HPAssist, added concise !HP controls, and preserved all !npc-hp, !NPCHP, and !NPCHPRoller compatibility commands and settings.
    //   Maintenance (v0.1.3, no semantic change): Added module narrative and aligned version metadata; HP rolling behavior unchanged.
    //   Maintenance (v0.1.1.2, no semantic change): MECHSUITS metadata updated for compliance.
    //   v0.1.7.0: Advanced NPCHPRoller to 0.1.1.2; Menu, GM, and DM open an action-focused HP control screen, with equivalent NPCHP and NPCHPRoller role aliases and unchanged HP-roll behavior.
    // [GAMEASSIST:MODULES:HPASSIST] END
    // =============================================================================

    // ————— DEBUG TOOLS MODULE v0.3.1 —————
    // =============================================================================
    // [GAMEASSIST:MODULES:DEBUGTOOLS] BEGIN
    // Section Title: DebugTools module
    // -------------------------------------------------------------------------
    // mechsuit_section: { codename: "GAMEASSIST", area: "MODULES:DEBUGTOOLS", title: "DebugTools",
    //   guarantees: ["Dry-run friendly debugging helpers","Compact guide, status, read-only audit, settings explanation, and unknown-command recovery use !ga-debug","Applied marker diagnostics use CORE:MARKERSERVICE","Applied damage uses verified HealthService provenance on supported HP surfaces and preserves the established direct fallback elsewhere"],
    //   depends_on: ["[GAMEASSIST:APP:UTILS]","[GAMEASSIST:CORE:MARKERSERVICE]","[GAMEASSIST:CORE:HEALTHSERVICE]","[GAMEASSIST:CORE:OBJECT]"],
    //   last_updated_version: "v2.0.0",
    //   independent_versions: { module_version: "0.3.1" } }
    // -------------------------------------------------------------------------
    // Narrative
    // MODULES:DEBUGTOOLS offers optional GM-only diagnostics for damage, markers, and
    // saves. It remains disabled by default, defaulting to dry-run behavior until
    // explicitly applied.
    // -------------------------------------------------------------------------
    GameAssist.register('DebugTools', function() {
        const modState = GameAssist.getState('DebugTools');
        const MODULE_VERSION = '0.3.1';
        let damageOperationSequence = 0;
        Object.assign(modState.config, {
            enabled: false,
            ...modState.config
        });

        function ensureDebugRuntime() {
            return ensureRuntimeObject(modState);
        }

        function wantsApply(args) {
            if (args.apply === undefined) return false;
            if (args.apply === false) return false;
            if (typeof args.apply === 'string') {
                return args.apply.toLowerCase() !== 'false';
            }
            return Boolean(args.apply);
        }

        function getTokenFromArgs(msg, args) {
            let tokenId = null;
            if (typeof args.token === 'string') tokenId = args.token;
            else if (Array.isArray(args.token) && args.token.length) tokenId = args.token[0];

            if (!tokenId && msg.selected?.length) {
                tokenId = msg.selected[0]._id;
            }

            if (!tokenId) return null;

            const token = getObj('graphic', tokenId);
            if (!token) {
                GameAssist.log('DebugTools', `Token ${tokenId} not found.`, 'WARN');
                return null;
            }
            if (token.get('layer') !== 'objects') {
                GameAssist.log('DebugTools', 'Token must be on the Objects layer.', 'WARN');
                return null;
            }
            return token;
        }

        function handleDamage(msg, args) {
            const token = getTokenFromArgs(msg, args);
            if (!token) {
                GameAssist.log('DebugTools', 'Select a token or pass --token <id> for damage tests.', 'WARN');
                return;
            }

            const amountRaw = args.amount ?? args.damage ?? args.value;
            const amount = Number(amountRaw);
            if (!Number.isFinite(amount) || amount <= 0) {
                GameAssist.log('DebugTools', 'Provide --amount <number> greater than zero.', 'WARN');
                return;
            }

            const hpFields = GameAssist.HealthService?.getHpFields?.() || { label: 'Bar 1', current: 'bar1_value' };
            const current = Number(token.get(hpFields.current)) || 0;
            const next    = Math.max(0, current - amount);
            const name    = _sanitize(token.get('name') || token.id);
            const summary = `${name}: HP ${current} → ${next} (-${amount})`;

            if (!wantsApply(args)) {
                GameAssist.log('DebugTools', `Dry run — would apply ${summary}. Add --apply to commit.`);
                return;
            }

            let verified = false;
            if (GameAssist.HealthService?.isEnabled?.()) {
                const result = GameAssist.HealthService.writeToken({
                    token,
                    current: next,
                    producer: 'DebugTools',
                    operationId: `debug-damage-${Date.now().toString(36)}-${++damageOperationSequence}`,
                    classification: 'damage'
                });
                if (result.ok) {
                    verified = result.verified === true;
                } else if (result.code !== 'UNPROCESSABLE') {
                    GameAssist.log('DebugTools', result.message || `HealthService damage write failed (${result.code || 'INTERNAL'}).`, 'WARN');
                    return;
                } else {
                    token.set(hpFields.current, next);
                }
            } else {
                token.set(hpFields.current, next);
            }
            GameAssist.log('DebugTools', `Applied ${summary}${verified ? ' through verified HealthService evidence' : ''}.`);
            ensureDebugRuntime().lastAction = { type: 'damage', token: token.id, amount, previous: current, verified };
        }

        function handleMarker(msg, args) {
            const token = getTokenFromArgs(msg, args);
            if (!token) {
                GameAssist.log('DebugTools', 'Select a token or pass --token <id> for marker tests.', 'WARN');
                return;
            }

            const markerRaw = args.marker ?? args.status;
            const marker = (markerRaw ? String(markerRaw) : 'blue').trim();
            if (!marker) {
                GameAssist.log('DebugTools', 'Provide --marker <status name>.', 'WARN');
                return;
            }

            const modeRaw = args.state ?? args.mode ?? args.action;
            const mode = modeRaw ? String(modeRaw).toLowerCase() : 'toggle';
            const inspection = GameAssist.MarkerService.inspect(token, marker);
            if (!inspection.ok) {
                GameAssist.log('DebugTools', inspection.message || `Marker lookup failed (${inspection.code || 'INTERNAL'}).`, 'WARN');
                return;
            }

            const action = (mode === 'on' || mode === 'add')
                ? 'add'
                : ((mode === 'off' || mode === 'remove' || mode === 'clear') ? 'remove' : 'toggle');
            const actionDesc = action === 'toggle'
                ? `${inspection.present ? 'remove' : 'add'} ${inspection.resolution.id}`
                : `${action} ${inspection.resolution.id}`;
            const name = _sanitize(token.get('name') || token.id);

            if (!wantsApply(args)) {
                GameAssist.log('DebugTools', `Dry run — would ${actionDesc} on ${name}. Add --apply to commit.`);
                return;
            }

            const result = action === 'add'
                ? GameAssist.MarkerService.add(token, marker, { owner: 'DebugTools' })
                : (action === 'remove'
                    ? GameAssist.MarkerService.remove(token, marker, { owner: 'DebugTools' })
                    : GameAssist.MarkerService.toggle(token, marker, { owner: 'DebugTools' }));
            if (!result.ok) {
                GameAssist.log('DebugTools', result.message || `Marker action failed (${result.code || 'INTERNAL'}).`, 'WARN');
                return;
            }

            GameAssist.log('DebugTools', `Marker action: ${actionDesc} on ${name}${result.changed ? '.' : ' (already in the requested state).'}`);
            ensureDebugRuntime().lastAction = {
                type: 'marker',
                token: token.id,
                marker: result.resolution.id,
                mode: action
            };
        }

        function handleSave(msg, args) {
            const dcRaw = args.dc ?? args.target;
            const dc = Number(dcRaw);
            if (!Number.isFinite(dc)) {
                GameAssist.log('DebugTools', 'Provide --dc <number> for save tests.', 'WARN');
                return;
            }

            const bonusRaw = args.bonus ?? args.mod ?? 0;
            const bonus = Number(bonusRaw) || 0;
            const modeRaw = args.mode ?? args.roll ?? '';
            const mode = typeof modeRaw === 'string' ? modeRaw.toLowerCase() : '';
            let expr = `1d20 + ${bonus}`;
            let descriptor = 'normal';
            if (mode.startsWith('adv')) {
                expr = `2d20kh1 + ${bonus}`;
                descriptor = 'advantage';
            } else if (mode.startsWith('dis')) {
                expr = `2d20kl1 + ${bonus}`;
                descriptor = 'disadvantage';
            }

            if (!wantsApply(args)) {
                GameAssist.log('DebugTools', `Dry run — would roll ${expr} vs DC ${dc} (${descriptor}). Add --apply to execute.`);
                return;
            }

            const label = args.label ? _sanitize(String(args.label)) : 'Debug Save';
            sendChat('', `[[${expr}]]`, ops => {
                const roll = ops?.[0]?.inlinerolls?.[0];
                if (!roll) {
                    GameAssist.log('DebugTools', 'Save roll failed.', 'WARN');
                    return;
                }
                const total = roll.results.total;
                const success = total >= dc;
                const outcome = success ? '✅ Success' : '❌ Failure';
                const template = `&{template:default} {{name=${label}}} {{Result=${total} vs DC ${dc}}} {{Outcome=${outcome} (${descriptor})}}`;
                sendChat('DebugTools', `/w gm ${template}`);
                GameAssist.log('DebugTools', `Rolled ${total} vs DC ${dc} (${descriptor}). ${success ? 'Success' : 'Failure'}.`);
            });
        }

        function sendDebugPanel(title, fields) {
            const body = fields.map(field => `{{${_sanitize(field.label)}=${field.value}}}`).join(' ');
            sendChat('DebugTools', `/w gm &{template:default} {{name=${_sanitize(title)}}} ${body}`);
        }

        function showHelp() {
            sendDebugPanel('DebugTools Guide', [
                { label: 'Actions', value: `${GameAssist.createButton('Damage Preview', '!ga-debug damage --amount ?{Damage|1}')} ${GameAssist.createButton('Marker Preview', '!ga-debug marker --marker ?{Marker|red}')} ${GameAssist.createButton('Save Preview', '!ga-debug save --dc ?{DC|10}')}` },
                { label: 'Learn Or Review', value: `${GameAssist.createButton('What does DebugTools do?', '!ga-debug info')} ${GameAssist.createButton('Current Status', '!ga-debug status')} ${GameAssist.createButton('Read-Only Audit', '!ga-debug audit')}` },
                { label: 'Safety', value: 'Preview is the default. A diagnostic changes a token or rolls a save only when the GM deliberately includes <code>--apply</code>.' }
            ]);
        }

        function showDebugControl() {
            sendDebugPanel('DebugTools GM Controls', [
                { label: 'Preview Diagnostics', value: `${GameAssist.createButton('Damage', '!ga-debug damage --amount ?{Damage|1}')} ${GameAssist.createButton('Marker', '!ga-debug marker --marker ?{Marker|red}')} ${GameAssist.createButton('Saving Throw', '!ga-debug save --dc ?{DC|10}')}` },
                { label: 'Review And Setup', value: `${GameAssist.createButton('Status', '!ga-debug status')} ${GameAssist.createButton('Read-Only Audit', '!ga-debug audit')} ${GameAssist.createButton('Settings', '!ga-debug settings')} ${GameAssist.createButton('Guide', '!ga-debug help')}` },
                { label: 'Safety', value: 'Every diagnostic is a preview until the GM deliberately adds <code>--apply</code>.' },
                { label: 'GameAssist', value: gameAssistHomeButton() }
            ]);
        }

        function showDebugInfo() {
            sendDebugPanel('What DebugTools Does', [
                { label: 'Purpose', value: 'Helps the GM preview controlled damage, marker, and saving-throw diagnostics while troubleshooting GameAssist behavior.' },
                { label: 'At The Table', value: 'Keep DebugTools disabled during ordinary play. Enable it for a focused check, preview the action, add <code>--apply</code> only when mutation is intended, then disable it again.' },
                { label: 'Continue', value: `${GameAssist.createButton('Back to Guide', '!ga-debug help')} ${GameAssist.createButton('Current Status', '!ga-debug status')}` }
            ]);
        }

        function showDebugStatus(audit = false) {
            const runtime = ensureDebugRuntime();
            const last = runtime.lastAction
                ? `${_sanitize(runtime.lastAction.type || 'action')} on ${_sanitize(runtime.lastAction.token || 'unknown token')}`
                : 'No applied diagnostic recorded in this runtime.';
            const fields = [
                { label: 'Module', value: `${MODULE_VERSION} | enabled and responding` },
                { label: 'Default Behavior', value: 'Dry-run preview; <code>--apply</code> is required for mutation or a live save roll.' },
                { label: 'MarkerService', value: GameAssist.MarkerService?.isEnabled?.() ? 'Available' : 'Unavailable' },
                { label: 'NPC HP Bar', value: GameAssist.HealthService?.getHpFields?.().label || 'Bar 1' },
                { label: 'Last Applied Action', value: last },
                { label: 'Actions', value: GameAssist.createButton('Open Guide', '!ga-debug help') }
            ];
            if (audit) fields.splice(4, 0, { label: 'Changes', value: 'None. This audit reads DebugTools runtime and service availability without running a diagnostic.' });
            sendDebugPanel(audit ? 'DebugTools Audit' : 'DebugTools Status', fields);
        }

        function showDebugSettings() {
            sendDebugPanel('DebugTools Settings', [
                { label: 'Module Setting', value: 'DebugTools has no separate behavior toggles. It is disabled by default, and each diagnostic is dry-run unless <code>--apply</code> is present.' },
                { label: 'Module Control', value: `${GameAssist.createButton('Disable DebugTools', '!ga-disable DebugTools')} ${GameAssist.createButton('Back to Guide', '!ga-debug help')}` }
            ]);
        }

        function showDebugManualNotice() {
            sendDebugPanel('DebugTools Guide', [
                { label: 'Manual', value: 'DebugTools is intentionally narrow, so its complete guidance stays in chat instead of creating a campaign handout.' },
                { label: 'Continue', value: `${GameAssist.createButton('Open Guide', '!ga-debug help')} ${GameAssist.createButton('Read-Only Audit', '!ga-debug audit')}` }
            ]);
        }

        const HANDLERS = {
            damage: handleDamage,
            marker: handleMarker,
            save: handleSave
        };

        function handleDebugCommand(msg) {
            const payload = String(msg.content || '')
                .replace(/^!(?:ga-debug|debugtools|debug)(?:-|\s)*/i, '');
            if (!payload) {
                showDebugControl();
                return;
            }

            const parsed = _parseArgs(payload);
            const action = (parsed.cmd || '').toLowerCase();
            if (action === 'help' || action === 'guide') {
                showHelp();
                return;
            }
            if (action === 'menu' || action === 'gm' || action === 'dm') {
                showDebugControl();
                return;
            }
            if (action === 'info' || action === 'about') {
                showDebugInfo();
                return;
            }
            if (action === 'status' || action === 'refresh') {
                showDebugStatus(false);
                return;
            }
            if (action === 'audit') {
                showDebugStatus(true);
                return;
            }
            if (action === 'settings' || action === 'config') {
                showDebugSettings();
                return;
            }
            if (action === 'manual') {
                showDebugManualNotice();
                return;
            }
            const handler = HANDLERS[action];
            if (!handler) {
                sendDebugPanel('DebugTools', [
                    { label: 'Needs Attention', value: 'That DebugTools command was not recognized.' },
                    { label: 'Next Step', value: GameAssist.createButton('Open Guide', '!ga-debug help') }
                ]);
                return;
            }
            handler(msg, parsed.args || {});
        }

        GameAssist.onCommand('!ga-debug', handleDebugCommand, 'DebugTools', { gmOnly: true });
        ['!Debug', '!DebugTools'].forEach(prefix => {
            GameAssist.onCommand(prefix, handleDebugCommand, 'DebugTools', {
                gmOnly: true,
                match: { caseInsensitive: true, mode: 'token' }
            });
        });
        ['!Debug-', '!DebugTools-'].forEach(prefix => {
            GameAssist.onCommand(prefix, handleDebugCommand, 'DebugTools', {
                gmOnly: true,
                match: { caseInsensitive: true, mode: 'prefix' }
            });
        });
        ['!Debug-GM', '!Debug-DM', '!DebugTools-GM', '!DebugTools-DM'].forEach(prefix => {
            GameAssist.onCommand(prefix, showDebugControl, 'DebugTools', { gmOnly: true });
        });

        GameAssist.log('DebugTools', 'Debug module registered. Enable with !ga-enable DebugTools when needed.', 'INFO', { startup: true });
    }, {
        enabled: false,
        prefixes: ['!ga-debug', '!Debug', '!Debug-', '!DebugTools', '!DebugTools-'],
        dependsOn: ['MarkerService']
    });
    // --- Notes & Comments ---
    // Changed (v2.0.0): Advanced DebugTools to 0.3.1; damage previews and fallback writes now follow HealthService's configured NPC HP bar instead of assuming bar 1, and bare Debug/DebugTools commands open the existing GM controls.
